/opt/news-flow/node/bin/node --input-type=module - <<'NODE'
import fs from 'node:fs';import {DatabaseSync} from 'node:sqlite';import {gunzipSync} from 'node:zlib';import {createRequire} from 'node:module';import {requestKey,urlAliases} from './src/newsFlow/identity.mjs';const require=createRequire('/opt/news-flow/current/package.json'),ch=require('cheerio'),db=new DatabaseSync('/var/lib/news-flow/news-flow-runtime/write.sqlite',{readOnly:true}),r={at:new Date().toISOString(),cache:[],tasks:db.prepare("SELECT cycle,url,url_key,created,role,state,reason FROM tasks WHERE site=? ORDER BY created DESC LIMIT 3").all('giacavattu.com.vn')};try{for(const task of r.tasks){const key=task.url_key,c=db.prepare('SELECT * FROM requests WHERE cycle=? AND url_key=?').get(task.cycle,key);if(!c)continue;let body=c.response;if(typeof body==='string')body=db.prepare('SELECT body FROM blobs WHERE hash=?').get(body)?.body;const row={key,updated:task.created,metadata:JSON.parse(c.metadata||'{}'),responseType:typeof c.response};delete row.metadata.html;delete row.metadata.proxyId;if(body){try{const html=gunzipSync(body).toString(),$=ch.load(html);row.title=$('title').text();row.feedLinks=$('a[href],link[href]').toArray().filter(e=>/rss|feed|gprss|syndicat/i.test($(e).attr('href')||'')).map(e=>({href:$(e).attr('href'),text:$(e).text()})).slice(0,20);row.times=html.match(/.{0,35}(?:datePublished|publication_date|pubDate|Cập nhật).{0,100}/g)?.slice(0,5);}catch(e){row.error=e.code||e.message;}}r.cache.push(row);}fs.writeFileSync('/var/lib/news-flow/qc-complete27-20261122/giacavattu-cache.json',JSON.stringify(r,null,2));console.log(JSON.stringify(r));}finally{db.close();}
NODE
install -o "$SUDO_USER" -m 0600 "$root/giacavattu-cache.json" "$upload_dir/.qc27-complete-giacavattu-cache.json"
